import RNA
import random, time, sys
from multiprocessing import Pool

target = "((((....).))).((((....).))).((((....).))).((((....).))).((((....).))).((((....).))).((((((((((((((((((((((...)))).))))))).(((((..((((((((((..(((((((...))))))).))))))))))((((.((((((...)))))))))))))))...))))))))))).((((....).))).((((....).))).((((....).))).((((....).))).((((....).)))"
n = len(target)
stack=[]; pairs={}
for i,c in enumerate(target):
    if c=='(':
        stack.append(i)
    elif c==')':
        j=stack.pop(); pairs[i]=j; pairs[j]=i

def fold_dist(seq):
    fc = RNA.fold_compound(seq)
    ss, mfe = fc.mfe()
    return RNA.bp_distance(ss, target), ss

def comp_init(seed):
    rnd = random.Random(seed)
    s=['A']*n
    for i in range(n):
        if target[i]=='(':
            j = pairs[i]
            p = rnd.choice(['GC','CG','AU','UA'])
            s[i]=p[0]; s[j]=p[1]
    for i in range(n):
        if target[i]=='.':
            s[i]=rnd.choice("ACGU")
    return ''.join(s)

def worker(seed):
    rnd = random.Random(seed)
    best = comp_init(seed)
    bd, _ = fold_dist(best)
    best_dist = bd
    t0 = time.time()
    while time.time()-t0 < 100 and best_dist > 0:
        cand = list(best)
        k = rnd.randint(1,5)
        for _ in range(k):
            i = rnd.randint(0,n-1)
            cand[i] = rnd.choice("ACGU")
        cand_s = ''.join(cand)
        d, _ = fold_dist(cand_s)
        if d <= best_dist or rnd.random() < 0.05:
            best = cand_s
            if d < best_dist:
                best_dist = d
        if best_dist == 0:
            return (0, best)
    return (best_dist, best)

if __name__ == '__main__':
    nproc = 60
    args = list(range(nproc))
    t0=time.time()
    with Pool(nproc) as p:
        results = p.map(worker, args)
    results.sort(key=lambda x: x[0])
    print("best dist", results[0][0], "time", time.time()-t0)
    print("SEQ", results[0][1])
    sys.stdout.flush()
    with open('/tmp/best_seq.txt','w') as f:
        f.write(results[0][1]+'\n')
        f.write(str(results[0][0])+'\n')
